//! Reader for the single-mesh, vertex-colored GLB generated by tools/about/export_kitchen.py.
//! The production renderer needs no JavaScript scene library or general-purpose glTF runtime.
use serde_json::Value;
pub struct KitchenMesh {
    pub vertices: Vec<f32>,
}
fn invalid() -> String {
    "Invalid kitchen model".into()
}
fn word(bytes: &[u8], at: usize) -> Result<u32, String> {
    Ok(u32::from_le_bytes(
        bytes
            .get(at..at + 4)
            .ok_or_else(invalid)?
            .try_into()
            .map_err(|_| invalid())?,
    ))
}
fn number(v: &Value, key: &str) -> Result<usize, String> {
    v[key].as_u64().map(|n| n as usize).ok_or_else(invalid)
}
fn view<'a>(doc: &Value, data: &'a [u8], index: usize) -> Result<&'a [u8], String> {
    let v = &doc["bufferViews"][index];
    if v["buffer"].as_u64() != Some(0) {
        return Err(invalid());
    }
    let start = v["byteOffset"].as_u64().unwrap_or(0) as usize;
    let len = number(v, "byteLength")?;
    data.get(start..start.checked_add(len).ok_or_else(invalid)?)
        .ok_or_else(invalid)
}
fn floats(doc: &Value, data: &[u8], index: usize, width: usize) -> Result<Vec<f32>, String> {
    let a = &doc["accessors"][index];
    if a["type"].as_str()
        != Some(if width == 2 {
            "VEC2"
        } else if width == 4 {
            "VEC4"
        } else {
            "VEC3"
        })
    {
        return Err(invalid());
    }
    let component = a["componentType"].as_u64().ok_or_else(invalid)?;
    let component_size = match component {
        5126 => 4,
        5122 | 5123 => 2,
        5121 => 1,
        _ => return Err(invalid()),
    };
    let count = number(a, "count")?;
    if count > 300_000 {
        return Err(invalid());
    }
    let vi = number(a, "bufferView")?;
    let bytes = view(doc, data, vi)?;
    let offset = a["byteOffset"].as_u64().unwrap_or(0) as usize;
    let stride = doc["bufferViews"][vi]["byteStride"]
        .as_u64()
        .unwrap_or((width * component_size) as u64) as usize;
    let mut out = Vec::with_capacity(count * width);
    for i in 0..count {
        for j in 0..width {
            let at = offset + i * stride + j * component_size;
            let v = match component {
                5121 => *bytes.get(at).ok_or_else(invalid)? as f32 / 255.,
                5126 => f32::from_bits(word(bytes, at)?),
                5123 => {
                    u16::from_le_bytes(
                        bytes
                            .get(at..at + 2)
                            .ok_or_else(invalid)?
                            .try_into()
                            .map_err(|_| invalid())?,
                    ) as f32
                        / 65535.
                }
                _ => (i16::from_le_bytes(
                    bytes
                        .get(at..at + 2)
                        .ok_or_else(invalid)?
                        .try_into()
                        .map_err(|_| invalid())?,
                ) as f32
                    / 32767.)
                    .max(-1.),
            };
            if !v.is_finite() {
                return Err(invalid());
            }
            out.push(v);
        }
    }
    Ok(out)
}
pub fn decode(bytes: &[u8]) -> Result<KitchenMesh, String> {
    if bytes.get(0..4) != Some(b"glTF")
        || word(bytes, 4)? != 2
        || word(bytes, 8)? as usize != bytes.len()
    {
        return Err(invalid());
    }
    let json_len = word(bytes, 12)? as usize;
    if word(bytes, 16)? != 0x4e4f534a {
        return Err(invalid());
    }
    let end = 20_usize.checked_add(json_len).ok_or_else(invalid)?;
    let doc: Value =
        serde_json::from_slice(bytes.get(20..end).ok_or_else(invalid)?).map_err(|_| invalid())?;
    let bin_len = word(bytes, end)? as usize;
    if word(bytes, end + 4)? != 0x004e4942 {
        return Err(invalid());
    }
    let data = bytes.get(end + 8..end + 8 + bin_len).ok_or_else(invalid)?;
    if doc["meshes"].as_array().map(Vec::len) != Some(1)
        || doc["meshes"][0]["primitives"].as_array().map(Vec::len) != Some(1)
    {
        return Err(invalid());
    }
    let p = &doc["meshes"][0]["primitives"][0];
    if p["mode"].as_u64().unwrap_or(4) != 4 {
        return Err(invalid());
    }
    let attr = &p["attributes"];
    let mut pos = floats(&doc, data, number(attr, "POSITION")?, 3)?;
    let node = &doc["nodes"][0];
    if node["rotation"].is_array() || node["matrix"].is_array() {
        return Err(invalid());
    }
    for (i, v) in pos.iter_mut().enumerate() {
        *v = *v * node["scale"][i % 3].as_f64().unwrap_or(1.) as f32
            + node["translation"][i % 3].as_f64().unwrap_or(0.) as f32;
    }
    let normals = floats(&doc, data, number(attr, "NORMAL")?, 3)?;
    let color_index = number(attr, "COLOR_0")?;
    let color_width = if doc["accessors"][color_index]["type"].as_str() == Some("VEC3") {
        3
    } else {
        4
    };
    let colors = floats(&doc, data, color_index, color_width)?;
    if normals.len() != pos.len() || colors.len() * 3 != pos.len() * color_width {
        return Err(invalid());
    }
    let a = &doc["accessors"][number(p, "indices")?];
    let count = number(a, "count")?;
    if count > 600_000 || count % 3 != 0 {
        return Err(invalid());
    }
    let vi = number(a, "bufferView")?;
    let ix = view(&doc, data, vi)?;
    let offset = a["byteOffset"].as_u64().unwrap_or(0) as usize;
    let size = match a["componentType"].as_u64() {
        Some(5123) => 2,
        Some(5125) => 4,
        _ => return Err(invalid()),
    };
    let mut vertices = Vec::with_capacity(count * 12);
    for k in 0..count {
        let at = offset + k * size;
        let i = if size == 4 {
            word(ix, at)? as usize
        } else {
            u16::from_le_bytes(
                ix.get(at..at + 2)
                    .ok_or_else(invalid)?
                    .try_into()
                    .map_err(|_| invalid())?,
            ) as usize
        };
        vertices.extend_from_slice(pos.get(i * 3..i * 3 + 3).ok_or_else(invalid)?);
        vertices.extend_from_slice(normals.get(i * 3..i * 3 + 3).ok_or_else(invalid)?);
        vertices.extend_from_slice(&[0., 0.]);
        for c in colors
            .get(i * color_width..i * color_width + 3)
            .ok_or_else(invalid)?
        {
            vertices.push(if *c <= 0.0031308 {
                c * 12.92
            } else {
                1.055 * c.powf(1. / 2.4) - 0.055
            });
        }
        vertices.push(1.);
    }
    Ok(KitchenMesh { vertices })
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn rejects_missing_or_invalid_glb() {
        for data in [&b""[..], &b"glTF"[..], &[0; 32][..]] {
            assert!(decode(data).is_err());
        }
    }
    #[test]
    fn delivered_kitchen_preserves_colors_and_fits_the_web_budget() {
        let bytes = include_bytes!("../../../assets/about/sams-kitchen.glb");
        let m = decode(bytes).unwrap();
        assert!(bytes.len() < 2_000_000);
        assert!(m.vertices.len() / 36 < 100_000);
        assert!(m.vertices.len() / 36 > 10_000);
        assert!(m.vertices.iter().all(|v| v.is_finite()));
        let colors = m
            .vertices
            .chunks_exact(12)
            .map(|v| [v[8].to_bits(), v[9].to_bits(), v[10].to_bits()])
            .collect::<std::collections::HashSet<_>>();
        assert!(
            colors.len() > 20,
            "The material palette must survive export"
        );
    }
}
